#!/usr/bin/env node
// Generates web/src/ux/data/labTabs.ts: every lab's tabs (id + label) pulled
// from web/src/labs/<lab>/index.tsx (plus the Web toolchain page), so the
// start page, the command palette and the lab help can deep-link to
// `#/<lab>?tab=<id>`.
//
//   node scripts/gen-lab-index.mjs
//
// Re-run it whenever a lab adds, removes or renames a tab, and commit the
// generated file. It only uses regular expressions — no TypeScript parser —
// so it looks for, in order:
//   1. `const TABS … = [ { id: 'x', label: 'Y' }, … ]`
//   2. the first `tabs={[ { id: 'x', label: 'Y' }, … ]}` passed to <Tabs>
// `native` records whether the page itself reads `?tab=` from the URL; for
// the others the navigation chrome clicks the matching tab button.
import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const labsDir = join(root, 'web/src/labs');
const out = join(root, 'web/src/ux/data/labTabs.ts');

/** Text between the bracket at `open` and its partner (exclusive). */
function balanced(src, open) {
  const pair = { '[': ']', '{': '}', '(': ')' };
  const stack = [];
  let quote = null;
  for (let i = open; i < src.length; i++) {
    const c = src[i];
    if (quote) {
      if (c === '\\') i++;
      else if (c === quote) quote = null;
      continue;
    }
    if (c === "'" || c === '"' || c === '`') quote = c;
    else if (pair[c]) stack.push(pair[c]);
    else if (c === stack[stack.length - 1]) {
      stack.pop();
      if (stack.length === 0) return src.slice(open + 1, i);
    }
  }
  return null;
}

const STR = String.raw`'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)"`;
const PAIR = new RegExp(String.raw`\{\s*id:\s*(?:${STR})\s*,\s*label:\s*(?:${STR})`, 'g');

function pairs(block) {
  const res = [];
  for (const m of block.matchAll(PAIR)) {
    const id = m[1] ?? m[2];
    const label = (m[3] ?? m[4]).replace(/\\(.)/g, '$1');
    res.push({ id, label });
  }
  return res;
}

function extract(src) {
  const named = /const\s+TABS\b[^=]*=\s*\[/.exec(src);
  if (named) {
    const block = balanced(src, named.index + named[0].length - 1);
    const p = block ? pairs(block) : [];
    if (p.length) return p;
  }
  const re = /tabs=\{\[/g;
  let m;
  while ((m = re.exec(src))) {
    const block = balanced(src, m.index + m[0].length - 1);
    const p = block ? pairs(block) : [];
    if (p.length) return p;
  }
  return [];
}

const entries = [];
for (const lab of readdirSync(labsDir).sort()) {
  const file = join(labsDir, lab, 'index.tsx');
  if (!existsSync(file)) continue;
  const src = readFileSync(file, 'utf8');
  entries.push({ key: lab, path: `/${lab}`, native: /get\(\s*['"]tab['"]\s*\)/.test(src), tabs: extract(src) });
}
// Pages outside src/labs that have tabs worth deep-linking.
for (const [key, rel] of [['toolchain', 'web/src/pages/Toolchain.tsx'], ['systems', 'web/src/pages/Systems.tsx']]) {
  const src = readFileSync(join(root, rel), 'utf8');
  entries.push({ key, path: `/${key}`, native: /get\(\s*['"]tab['"]\s*\)/.test(src), tabs: extract(src) });
}

const q = (s) => JSON.stringify(s);
let ts = `// GENERATED by scripts/gen-lab-index.mjs — do not edit by hand.
// Regenerate with \`node scripts/gen-lab-index.mjs\` after a lab adds or renames a tab.

export interface TabRef {
  id: string;
  label: string;
}

export interface PageTabs {
  path: string;
  /** true when the page reads \`?tab=\` itself; otherwise the chrome clicks the tab. */
  native: boolean;
  tabs: TabRef[];
}

export const LAB_TABS: Record<string, PageTabs> = {
`;
for (const e of entries) {
  ts += `  ${/^[a-z_]\w*$/i.test(e.key) ? e.key : q(e.key)}: { path: ${q(e.path)}, native: ${e.native}, tabs: [${e.tabs.map((t) => `{ id: ${q(t.id)}, label: ${q(t.label)} }`).join(', ')}] },\n`;
}
ts += `};\n`;
writeFileSync(out, ts);
const empty = entries.filter((e) => e.tabs.length === 0).map((e) => e.key);
console.log(`wrote ${out}: ${entries.length} pages, ${entries.reduce((a, e) => a + e.tabs.length, 0)} tabs${empty.length ? `; no tabs found for ${empty.join(', ')}` : ''}`);
